const request = $items('Set Read-Only Reconciliation Request')[0].json;
const detail = $items('Get Helper Detail Telemetry From Helper')[0].json || {};
const lock = $json || {};
const classificationSummary = detail.classification_summary || {};
const finalClassification = String(classificationSummary.final_classification || detail.classification || 'unknown_stop');
const lockState = String(lock.lock_state || 'unknown_stop');
const lockExists = lock.lock_exists === true;
const staleLock = lock.stale_lock === true || lockState === 'stale_stop';
const lockStatusClear = lock.success === true && lockState === 'unlocked' && lockExists === false && staleLock === false;
const openOrderCount = Number(detail.open_order_count ?? 0);
const openOrderExists = detail.open_order_exists === true || openOrderCount > 0;
const duplicateRaw = detail.duplicate_order_exists;
const duplicateKnown = duplicateRaw === true || duplicateRaw === false;
const duplicateOrderExists = duplicateRaw === true;
const detailSuccess = detail.success === true;
const finalReconciliation = ['done', 'cancel'].includes(finalClassification);
const blockedReasons = [];
if (!detailSuccess) blockedReasons.push((classificationSummary.blocked_reason || detail.error_message || detail.error_name || 'HELPER_DETAIL_UNAVAILABLE'));
if (openOrderExists) blockedReasons.push('OPEN_ORDER_EXISTS');
if (openOrderCount !== 0) blockedReasons.push('OPEN_ORDER_COUNT_NOT_ZERO');
if (!duplicateKnown) blockedReasons.push('DUPLICATE_ORDER_STATUS_UNCLEAR');
if (duplicateOrderExists) blockedReasons.push('DUPLICATE_ORDER_EXISTS');
if (!finalReconciliation) blockedReasons.push('RECONCILIATION_UNCLEAR');
if (lock.success !== true && lockState !== 'stale_stop') blockedReasons.push(lock.blocked_reason || 'LOCK_UNAVAILABLE');
if (lockExists && !staleLock) blockedReasons.push(lock.blocked_reason || 'ACTIVE_LOCK_EXISTS');
if (staleLock) blockedReasons.push('STALE_LOCK_EXISTS');
if (!lockStatusClear && !staleLock && !lockExists && lock.success !== true) blockedReasons.push('LOCK_STATUS_UNCLEAR');
const uniqueBlockedReasons = [...new Set(blockedReasons.filter(Boolean))];
let lockClassification = 'lock_clear_read_only';
let humanReviewRequired = false;
if (staleLock) {
  lockClassification = 'stale_lock_stop';
  humanReviewRequired = true;
} else if (lockExists) {
  lockClassification = 'active_lock_stop';
  humanReviewRequired = true;
} else if (!lockStatusClear) {
  lockClassification = 'lock_unknown_stop';
  humanReviewRequired = true;
}
const overallClassification = uniqueBlockedReasons.length === 0 ? 'readonly_reconciliation_lock_clear' : 'readonly_stop';
const timestampKst = new Date().toLocaleString('sv-SE', { timeZone: 'Asia/Seoul', hour12: false }).replace('T', ' ') + ' +09:00';
const safeLog = {
  timestamp_kst: timestampKst,
  workflow_name: 'WF05_Reconciliation_ReadOnly',
  market: String(detail.market || request.market || 'KRW-BTC'),
  open_order_exists: openOrderExists,
  open_order_count: openOrderCount,
  duplicate_order_exists: duplicateKnown ? duplicateOrderExists : null,
  reconciliation_classification: finalClassification,
  lock_state: lockState,
  lock_exists: lockExists,
  stale_lock: staleLock,
  lock_classification: lockClassification,
  classification: overallClassification,
  blocked_reason: uniqueBlockedReasons.length > 0 ? uniqueBlockedReasons.join('|') : null,
  human_review_required: humanReviewRequired,
  forbidden_endpoint_check: 'PASS_READ_ONLY_DETAIL_AND_LOCK_STATUS_ONLY',
  secrets_leak_check: 'PASS_NO_SECRET_FIELDS_PRESENT',
  next_safe_action: uniqueBlockedReasons.length > 0 ? 'remain_stopped_and_review' : 'remain_stopped'
};
return {
  workflow_name: 'WF05_Reconciliation_ReadOnly',
  read_only: true,
  reconciliation_status: overallClassification,
  classification: overallClassification,
  reconciliation_classification: finalClassification,
  lock_classification: lockClassification,
  blocked_reason: safeLog.blocked_reason,
  human_review_required: humanReviewRequired,
  execution_allowed: false,
  live_order_allowed: false,
  automation_allowed: false,
  lock_acquire_attempted: false,
  lock_release_attempted: false,
  auto_unlock_attempted: false,
  retry_attempted: false,
  live_order_attempted: false,
  forbidden_action_attempted: false,
  workflow_activation_changed: false,
  helper_detail_telemetry: {
    success: detail.success ?? null,
    market: safeLog.market,
    open_order_exists: openOrderExists,
    open_order_count: openOrderCount,
    duplicate_order_exists: safeLog.duplicate_order_exists,
    classification_summary: classificationSummary,
    forbidden_endpoint_check: detail.forbidden_endpoint_check ?? null,
    secrets_leak_check: detail.secrets_leak_check ?? null
  },
  execution_lock_status: {
    success: lock.success ?? null,
    lock_state: lockState,
    lock_exists: lockExists,
    stale_lock: staleLock,
    human_review_required: lock.human_review_required === true,
    blocked_reason: lock.blocked_reason ?? null
  },
  current_reconciliation: {
    open_order_exists: openOrderExists,
    open_order_count: openOrderCount,
    market: safeLog.market,
    classification: finalClassification,
    lock_state: lockState,
    stale_lock: staleLock
  },
  safe_reconciliation_log_payload: safeLog
};

return {
  ...$json,
  append_only_log_ready: true,
  log_sink: 'external_safe_append_only_required',
  safe_reconciliation_log_payload: {
    ...$json.safe_reconciliation_log_payload,
    forbidden_endpoint_check: 'PASS_NO_FORBIDDEN_ENDPOINT_CALLED',
    secrets_leak_check: 'PASS_NO_SECRET_FIELDS_PRESENT'
  }
};
